# Apply one simultaneous mapping to headings and contents, preserving source numbering.
for p in d.paragraphs:
 t=p.text
 if p.style.name.startswith('Heading') or (t.startswith(('2 ','2.','4 ','4.')) and p._p.getprevious() is not None and len(t)<130):
  if re.match(r'^2(?: |\.)',t): t=re.sub(r'^2','1',t)
  elif re.match(r'^4(?: |\.)',t):
   m=re.match(r'^4\.(\d+)',t)
   if m: t=re.sub(r'^4\.\d+', '2.'+str(int(m[1])+(3 if int(m[1])>=3 else 0)),t)
   else: t=re.sub('^4','2',t)
 if t.startswith('Таблиця 2.1'): t=t.replace('Таблиця 2.1','Таблиця 1.1',1)
 elif t.startswith('Таблиця 4.'): t=t.replace('Таблиця 4.','Таблиця 2.',1)
 t=t.replace('таблиці 4.4','таблиці 2.4')
 if t!=p.text:
  # Paragraph styles are retained; these replacements contain no inline emphasis.
  p.text=t
